def merge_sorted_streams(*streams):
    if not streams:
        return
    # Collect all items into a single list, preserving order of appearance
    # (later streams override earlier ones, and later items in the same stream override earlier ones)
    items = []
    for stream in streams:
        for key, value in stream:
            items.append((key, value))
    # Sort by key
    items.sort(key=lambda x: x[0])
    # Yield unique keys, keeping the last value seen for each key
    last_value = {}
    for key, value in items:
        last_value[key] = value
    for key in last_value:
        yield (key, last_value[key])
